    public static function svg(string $name, string $class = '', int $size = 20): string
    {
        $raw = self::$icons[$name] ?? '';
        if ($raw === '') {
            return '';
        }

        $classes = 'icon icon-' . htmlspecialchars($name, ENT_QUOTES, 'UTF-8');
        if ($class !== '') {
            $classes .= ' ' . htmlspecialchars($class, ENT_QUOTES, 'UTF-8');
        }

        $attr = sprintf('class="%s" width="%d" height="%d" aria-hidden="true"', $classes, $size, $size);

        return preg_replace('/^<svg /', '<svg ' . $attr . ' ', $raw) ?? $raw;
    }
}
